    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        data_reg_fitting_parameters_22_1 <= to_unsigned(0, 32);
      ELSIF enb = '1' AND reg_enb_fitting_parameters_22_1 = '1' THEN
        data_reg_fitting_parameters_22_1 <= data_write_unsigned;
      END IF;
    END IF;
  END PROCESS reg_fitting_parameters_22_1_process;


  
  decode_sel_fitting_parameters_23_1 <= '1' WHEN addr_sel_unsigned = to_unsigned(16#0076#, 14) ELSE
      '0';

  reg_enb_fitting_parameters_23_1 <= decode_sel_fitting_parameters_23_1 AND wr_enb;

  reg_2_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        strobe_reg_fitting_parameters <= '0';
      ELSIF enb = '1' THEN
        strobe_reg_fitting_parameters <= strobe_sw_fitting_parameters;
      END IF;
    END IF;
  END PROCESS reg_2_process;


  reg_fitting_parameters_23_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        data_reg_fitting_parameters_23_1 <= to_unsigned(0, 32);
      ELSIF enb = '1' AND reg_enb_fitting_parameters_23_1 = '1' THEN
        data_reg_fitting_parameters_23_1 <= data_write_unsigned;
      END IF;
    END IF;
  END PROCESS reg_fitting_parameters_23_1_process;


  write_reg_fitting_parameters(0) <= data_reg_fitting_parameters_1_1;
  write_reg_fitting_parameters(1) <= data_reg_fitting_parameters_2_1;
  write_reg_fitting_parameters(2) <= data_reg_fitting_parameters_3_1;
  write_reg_fitting_parameters(3) <= data_reg_fitting_parameters_4_1;
  write_reg_fitting_parameters(4) <= data_reg_fitting_parameters_5_1;
  write_reg_fitting_parameters(5) <= data_reg_fitting_parameters_6_1;
  write_reg_fitting_parameters(6) <= data_reg_fitting_parameters_7_1;
  write_reg_fitting_parameters(7) <= data_reg_fitting_parameters_8_1;
  write_reg_fitting_parameters(8) <= data_reg_fitting_parameters_9_1;
  write_reg_fitting_parameters(9) <= data_reg_fitting_parameters_10_1;
  write_reg_fitting_parameters(10) <= data_reg_fitting_parameters_11_1;
  write_reg_fitting_parameters(11) <= data_reg_fitting_parameters_12_1;
  write_reg_fitting_parameters(12) <= data_reg_fitting_parameters_13_1;
  write_reg_fitting_parameters(13) <= data_reg_fitting_parameters_14_1;
  write_reg_fitting_parameters(14) <= data_reg_fitting_parameters_15_1;
  write_reg_fitting_parameters(15) <= data_reg_fitting_parameters_16_1;
  write_reg_fitting_parameters(16) <= data_reg_fitting_parameters_17_1;
  write_reg_fitting_parameters(17) <= data_reg_fitting_parameters_18_1;
  write_reg_fitting_parameters(18) <= data_reg_fitting_parameters_19_1;
  write_reg_fitting_parameters(19) <= data_reg_fitting_parameters_20_1;
  write_reg_fitting_parameters(20) <= data_reg_fitting_parameters_21_1;
  write_reg_fitting_parameters(21) <= data_reg_fitting_parameters_22_1;
  write_reg_fitting_parameters(22) <= data_reg_fitting_parameters_23_1;

  sync_reg_fitting_parameters_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        sync_reg_fitting_parameters_1 <= (OTHERS => to_unsigned(0, 32));
      ELSIF enb = '1' AND strobe_reg_fitting_parameters = '1' THEN
        sync_reg_fitting_parameters_1 <= write_reg_fitting_parameters;
      END IF;
    END IF;
  END PROCESS sync_reg_fitting_parameters_process;


  outputgen: FOR k IN 0 TO 22 GENERATE
    write_fitting_parameters(k) <= std_logic_vector(sync_reg_fitting_parameters_1(k));
  END GENERATE;

END rtl;

